<?php
declare(strict_types=1);
$alliances=$db->query('SELECT a.id,a.name,a.tag,a.leader_id,p.username AS leader_name,a.created_at,(SELECT COUNT(*) FROM alliance_members m WHERE m.alliance_id=a.id) AS member_count FROM alliances a LEFT JOIN players p ON p.id=a.leader_id WHERE a.world_id=? ORDER BY member_count DESC,a.id LIMIT 100',[$selectedWorld])->fetchAll();
?>
<section class="card"><h2>Allianzen dieser Welt</h2><p>Mitgliedschaft und Führung im Überblick.</p><div class="table-wrap"><table><thead><tr><th>Allianz</th><th>Führung</th><th>Mitglieder</th><th>Gegründet (UTC)</th></tr></thead><tbody><?php foreach($alliances as $a): ?><tr><td>[<?= ah($a['tag']) ?>] <?= ah($a['name']) ?></td><td><a href="<?= APP_BASE ?>/admin/players/<?= (int)$a['leader_id'] ?>?world_id=<?= $selectedWorld ?>"><?= ah($a['leader_name']) ?></a></td><td><?= an($a['member_count']) ?></td><td><?= ah($a['created_at']) ?></td></tr><?php endforeach ?></tbody></table></div><?php if(!$alliances): ?><p class="empty">In dieser Welt wurde noch keine Allianz gegründet.</p><?php endif ?></section>
